const D = { scale:1, energy:.6, hue:290, speed:1, density:.6, x:.5, y:.9, spin:1, glitch:.4, style:'flat', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const md=(a,n)=>((a%n)+n)%n;
const lrp=(a,b,t)=>a+(b-a)*t;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};

const W=width,Hh=height,u=Math.min(W,Hh);
const H=md(P.hue,360);
const st=P.style;
const flat=st==='flat', neon=st==='neon', chrome=st==='chrome', blueprint=st==='blueprint', vhs=st==='vhs';
const outlineOnly=blueprint;
const en=P.energy*(0.6+0.5*K.intensity);

if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat;
S.lastBeat=K.beat;

const bw=Math.round(u*1.2*P.scale), bh=Math.round(u*0.5*P.scale);
const bx0=P.x*W-bw*0.5, by0=P.y*Hh-bh;

// layout (local coords)
const tableY=bh*0.30;
const frontTop=tableY+bh*0.11, frontBot=bh;
const lp={x:bw*0.24,y:tableY-bh*0.02,rx:bw*0.155,ry:bw*0.155*0.42};
const rp={x:bw*0.76,y:tableY-bh*0.02,rx:bw*0.155,ry:bw*0.155*0.42};
const mix={x:bw*0.5,y:tableY-bh*0.01,w:bw*0.22,h:bh*0.16};
const logo={x:bw*0.5,y:frontTop+(frontBot-frontTop)*0.34,w:bw*0.42,h:(frontBot-frontTop)*0.4};
const vu={x:bw*0.5,y:frontBot-(frontBot-frontTop)*0.16,w:bw*0.82,h:(frontBot-frontTop)*0.24,n:Math.round(lrp(12,26,clp(P.density,0,1)))};

function acc(){ return blueprint?[190,55,100]: neon?[md(H,360),90,100]: chrome?[200,8,92]: [md(H,360),80,95]; }

// ---- cached chassis ----
const key=bw+'x'+bh+':'+st+':'+P.seed+':'+Math.round(H/6);
if(!S.base||S.key!==key){
  S.key=key;
  const g=createGraphics(bw,bh); g.colorMode(HSB,360,100,100,100);
  if(blueprint) g.background(220,70,24); else g.clear();
  const A2=acc();
  // front face
  if(outlineOnly){ g.noFill(); g.stroke(190,50,100,80); g.strokeWeight(Math.max(1,bw*0.001)); g.rect(0,frontTop,bw,frontBot-frontTop); }
  else{
    const faceB= chrome?22: neon?9: 16;
    g.noStroke(); g.fill(md(H,360),chrome?6:28,faceB); g.rect(0,frontTop,bw,frontBot-frontTop);
    // brushed / grille texture
    if(chrome){ for(let i=0;i<40;i++){ const yy=frontTop+(frontBot-frontTop)*fr(i*2); g.stroke(200,6,lrp(30,60,fr(i*2+1)),40); g.strokeWeight(0.7); g.line(0,yy,bw,yy);} g.noStroke(); }
    else{ g.fill(0,0,0,22); for(let i=0;i<26;i++){ g.rect(bw*0.06,frontTop+ (i+1)*(frontBot-frontTop)/28, bw*0.30, 1.5);} }
    // top bevel
    g.fill(md(H,360),chrome?4:20, faceB+16); g.rect(0,frontTop-bh*0.02,bw,bh*0.02);
    if(neon){ g.stroke(md(H,360),90,100,80); g.strokeWeight(2); g.noFill(); g.rect(1,frontTop,bw-2,frontBot-frontTop-1); g.noStroke(); }
  }
  // table surface band
  if(!outlineOnly){ g.noStroke(); g.fill(md(H,360),chrome?4:16, chrome?34:12); g.quad(bw*0.02,tableY,bw*0.98,tableY,bw,frontTop,0,frontTop); }
  else { g.stroke(190,50,100,60); g.line(0,frontTop,bw,frontTop); }
  // platters (vinyl discs) + grooves + tonearm
  function deck(d){
    g.push(); g.translate(d.x,d.y);
    if(outlineOnly){ g.noFill(); g.stroke(190,55,100,80); g.strokeWeight(1.2); g.ellipse(0,0,d.rx*2,d.ry*2);
      for(let r=0.8;r>0.25;r-=0.25) g.ellipse(0,0,d.rx*2*r,d.ry*2*r); }
    else{
      g.noStroke(); g.fill(0,0,0,50); g.ellipse(d.ry*0.3,d.ry*0.4,d.rx*2.05,d.ry*2.05); // shadow
      g.fill(0,0, neon?6:7); g.ellipse(0,0,d.rx*2,d.ry*2);
      g.stroke(0,0,neon?30:20,60); g.strokeWeight(0.6); g.noFill();
      for(let r=0.9;r>0.34;r-=0.09) g.ellipse(0,0,d.rx*2*r,d.ry*2*r);
      g.noStroke();
      if(neon){ g.noFill(); g.stroke(md(H,360),90,100,70); g.strokeWeight(2); g.ellipse(0,0,d.rx*2,d.ry*2); g.noStroke(); }
    }
    // tonearm (static)
    g.stroke(0,0, blueprint?100:70, blueprint?70:100); g.strokeWeight(Math.max(1.5,bw*0.004));
    g.line(d.rx*0.9,-d.ry*1.1, d.rx*0.2, -d.ry*0.1); g.noStroke();
    if(!outlineOnly){ g.fill(0,0,70); g.ellipse(d.rx*0.9,-d.ry*1.1,bw*0.02,bw*0.02); }
    g.pop();
  }
  deck(lp); deck(rp);
  // mixer chassis
  g.push(); g.translate(mix.x,mix.y);
  if(outlineOnly){ g.noFill(); g.stroke(190,55,100,80); g.strokeWeight(1); g.rect(-mix.w/2,-mix.h,mix.w,mix.h+mix.h*0.2); }
  else{ g.noStroke(); g.fill(md(H,360),6,chrome?40:18); g.rect(-mix.w/2,-mix.h,mix.w,mix.h+mix.h*0.2,2); }
  // faders
  for(let i=0;i<4;i++){ const fx=-mix.w*0.32+i*mix.w*0.21;
    if(outlineOnly){ g.stroke(190,55,100,70); g.strokeWeight(1); g.line(fx,-mix.h*0.85,fx,-mix.h*0.15);}
    else{ g.stroke(0,0,40,80); g.strokeWeight(2); g.line(fx,-mix.h*0.85,fx,-mix.h*0.15);
      g.noStroke(); g.fill(acc()[0],acc()[1],acc()[2]); g.rect(fx-mix.w*0.03,-mix.h*(0.7-fr(i)*0.4),mix.w*0.06,mix.h*0.12,1);} }
  g.noStroke(); g.pop();
  // cable spaghetti (static beziers)
  const cc= blueprint?[190,50,90]: neon?[md(H+40,360),70,80]:[md(H,360),20,10];
  g.noFill(); g.stroke(cc[0],cc[1],cc[2], blueprint?60:75); g.strokeWeight(Math.max(1.5,bw*0.004));
  for(let i=0;i<5;i++){ const sx=bw*(0.2+fr(i*5)*0.6), ey=frontBot, ex=bw*(0.15+fr(i*5+1)*0.7);
    g.bezier(sx,tableY+bh*0.02, sx+ (fr(i*5+2)-0.5)*bw*0.2, tableY+bh*0.2, ex+(fr(i*5+3)-0.5)*bw*0.2, ey-bh*0.05, ex, ey); }
  g.noStroke();
  // logo panel frame
  if(outlineOnly){ g.noFill(); g.stroke(190,55,100,80); g.strokeWeight(1.4); g.rect(logo.x-logo.w/2,logo.y-logo.h/2,logo.w,logo.h); }
  else{ g.noStroke(); g.fill(0,0,4); g.rect(logo.x-logo.w/2,logo.y-logo.h/2,logo.w,logo.h,3);
    g.fill(md(H,360),40,14); g.rect(logo.x-logo.w/2+2,logo.y-logo.h/2+2,logo.w-4,logo.h-4,3); }
  S.base=g;
}
image(S.base,bx0,by0,bw,bh);

// ---- spinning platter markers (continuous via K.t = motion floor) ----
const rot=K.t*P.spin*P.speed*4.2;
noStroke();
function spinLabel(d,dir){
  const cx=bx0+d.x, cy=by0+d.y;
  const A2=acc();
  // label
  if(blueprint){ noFill(); stroke(190,55,100,80); strokeWeight(1); ellipse(cx,cy,d.rx*0.8,d.ry*0.8); noStroke(); }
  else{ fill(A2[0],A2[1],A2[2],neon?70:100); ellipse(cx,cy,d.rx*0.8,d.ry*0.8); fill(0,0,6); ellipse(cx,cy,d.rx*0.14,d.ry*0.14); }
  // rotating marker dot (elliptical path -> reads as spin)
  const a=rot*dir;
  const mx=cx+Math.cos(a)*d.rx*0.55, my=cy+Math.sin(a)*d.ry*0.55;
  fill(blueprint?190:0,blueprint?55:0,100, blueprint?80:100); ellipse(mx,my,d.rx*0.10,d.rx*0.10);
  if(neon){ blendMode(ADD); fill(A2[0],90,100,60); ellipse(mx,my,d.rx*0.2,d.rx*0.2); blendMode(BLEND); }
}
spinLabel(lp,1); spinLabel(rp,-1);

// ---- logo panel pulse (bass + K baseline) ----
const pulse=clp(0.42+0.35*Math.sin(K.t*1.4*P.speed)+K.pulse*0.5*en+A.bass*0.8,0,1.4);
const A3=acc();
if(neon||flat||vhs){ blendMode(ADD); }
noStroke();
fill(A3[0],A3[1],A3[2], (outlineOnly?18:40)*pulse);
rect(bx0+logo.x-logo.w/2+3,by0+logo.y-logo.h/2+3,logo.w-6,logo.h-6,3);
// logo emblem: pulsing concentric bars
for(let i=0;i<3;i++){ const ph=1-i*0.28; fill(md(H+i*22,360),70,100,(outlineOnly?20:55)*pulse*ph);
  rect(bx0+logo.x-logo.w*0.34,by0+logo.y-logo.h*0.12+i*logo.h*0.16,logo.w*0.68*(0.5+0.5*pulse),logo.h*0.08,2); }
blendMode(BLEND);

// ---- VU meters (K baseline bounce, A.fft on top) ----
const bx=bx0+vu.x-vu.w/2, byb=by0+vu.y+vu.h/2;
const bwid=vu.w/vu.n;
noStroke();
for(let i=0;i<vu.n;i++){
  const fftv=(A.fft&&A.fft.length)? (A.fft[Math.floor(i/vu.n*A.fft.length)]||0):0;
  const base=0.30+0.32*Math.max(0,Math.sin(K.t*(2.2+i*0.12)*P.speed + i*0.5))+0.22*K.pulse+0.12*Math.sin(K.t*0.5+i);
  const amp=clp(base*(0.5+en)+fftv*1.3,0.04,1);
  const barH=amp*vu.h;
  const segs=Math.max(3,Math.round(barH/(vu.h/12)));
  for(let s2=0;s2<segs;s2++){ const f=s2/12; const yy=byb-s2*(vu.h/12)-vu.h/24;
    let col; if(blueprint) col=[190,55,100]; else if(f<0.55) col=[md(H+90,360),80,95]; else if(f<0.8) col=[45,90,100]; else col=[8,90,100];
    if(neon||flat||vhs) blendMode(ADD);
    fill(col[0],col[1],col[2], outlineOnly?55:88); rect(bx+i*bwid+bwid*0.14,yy,bwid*0.72,vu.h/12*0.72,1);
    blendMode(BLEND);
  }
}

// ---- vhs glitch (partial-frame bands, strobe-safe) ----
if(vhs){
  // scanlines
  blendMode(MULTIPLY); noStroke(); fill(0,0,0,30);
  for(let y=by0;y<by0+bh;y+=3) rect(bx0,y,bw,1.2);
  blendMode(BLEND);
  // occasional rgb-offset tear band driven by K.t
  const gt=Math.sin(K.t*0.9)*0.5+0.5;
  if(gt>1-P.glitch*0.6){ const by2=by0+bh*(0.2+0.6*(fr(Math.floor(K.t*2))));
    blendMode(ADD); noStroke();
    fill(0,90,100,20); rect(bx0-bw*0.01,by2,bw,bh*0.05);
    fill(160,90,100,20); rect(bx0+bw*0.01,by2,bw,bh*0.05);
    blendMode(BLEND);
  }
}
blendMode(BLEND);
drawingContext.shadowBlur=0;
